    10	@RestControllerAdvice
    11	public class GlobalExceptionHandler {
    12	
    13	    private static final MediaType PROBLEM_JSON = MediaType.valueOf("application/problem+json");
    14	
    15	    @ExceptionHandler(PostNotFoundException.class)
    16	    public ResponseEntity<ProblemResponse> handlePostNotFound(PostNotFoundException ex) {
    17	        ProblemResponse body = new ProblemResponse(
    18	                "about:blank", "Post not found", HttpStatus.NOT_FOUND.value(), ex.getMessage());
    19	        return ResponseEntity.status(HttpStatus.NOT_FOUND).contentType(PROBLEM_JSON).body(body);
    20	    }
    21	
    22	    @ExceptionHandler(MethodArgumentNotValidException.class)
    23	    public ResponseEntity<ProblemResponse> handleValidation(MethodArgumentNotValidException ex) {
    24	        String detail = ex.getBindingResult().getAllErrors().isEmpty()
    25	                ? "invalid request"
    26	                : ex.getBindingResult().getAllErrors().get(0).getDefaultMessage();
    27	        ProblemResponse body = new ProblemResponse(
    28	                "about:blank", "Validation failed", HttpStatus.BAD_REQUEST.value(), detail);
    29	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).contentType(PROBLEM_JSON).body(body);
    30	    }
    31	}
