     9	import org.springframework.kafka.core.KafkaTemplate;
    10	import org.springframework.stereotype.Component;
    11	
    12	import java.time.Clock;
    13	import java.time.Instant;
    14	import java.util.LinkedHashMap;
    15	import java.util.Map;
    16	
    17	/**
    18	 * community 가 발행하는 세 이벤트(post.created / comment.created / mood.logged)를
    19	 * JSON 문자열로 Kafka 에 발행한다. 추적 헤더 없음, 페이로드는 자기완결적.
    20	 */
    21	@Component
    22	public class CommunityEventPublisher {
    23	
    24	    private final KafkaTemplate<String, String> kafkaTemplate;
    25	    private final ObjectMapper objectMapper;
    26	    private final IdGenerator idGenerator;
    27	    private final Clock clock;
    28	    private final String postCreatedTopic;
    29	    private final String commentCreatedTopic;
    30	    private final String moodLoggedTopic;
    31	
    32	    public CommunityEventPublisher(KafkaTemplate<String, String> kafkaTemplate,
    33	                                   ObjectMapper objectMapper,
    34	                                   IdGenerator idGenerator,
    35	                                   Clock clock,
    36	                                   @Value("${community.topics.post-created}") String postCreatedTopic,
    37	                                   @Value("${community.topics.comment-created}") String commentCreatedTopic,
    38	                                   @Value("${community.topics.mood-logged}") String moodLoggedTopic) {
    39	        this.kafkaTemplate = kafkaTemplate;
    40	        this.objectMapper = objectMapper;
    41	        this.idGenerator = idGenerator;
    42	        this.clock = clock;
    43	        this.postCreatedTopic = postCreatedTopic;
    44	        this.commentCreatedTopic = commentCreatedTopic;
    45	        this.moodLoggedTopic = moodLoggedTopic;
    46	    }
    47	
    48	    /** post.created {eventId, postId, userId, category, moodEmoji, occurredAt} */
    49	    public void publishPostCreated(Post post) {
    50	        Map<String, Object> payload = new LinkedHashMap<String, Object>();
    51	        payload.put("eventId", idGenerator.newId());
    52	        payload.put("postId", post.getId());
    53	        payload.put("userId", post.getUserId());
    54	        payload.put("category", post.getCategory());
    55	        payload.put("moodEmoji", post.getMoodEmoji());
    56	        payload.put("occurredAt", Instant.now(clock).toString());
    57	        send(postCreatedTopic, post.getId(), payload);
    58	    }
    59	
    60	    /** mood.logged {eventId, userId, source, mood, score, occurredAt} (source='community', mood=moodEmoji, score=0) */
    61	    public void publishMoodLogged(Post post) {
    62	        Map<String, Object> payload = new LinkedHashMap<String, Object>();
    63	        payload.put("eventId", idGenerator.newId());
    64	        payload.put("userId", post.getUserId());
    65	        payload.put("source", "community");
    66	        payload.put("mood", post.getMoodEmoji());
    67	        payload.put("score", 0);
    68	        payload.put("occurredAt", Instant.now(clock).toString());
    69	        send(moodLoggedTopic, post.getUserId(), payload);
    70	    }
    71	
    72	    /** comment.created {eventId, postId, commentId, postAuthorUserId, role, occurredAt} */
    73	    public void publishCommentCreated(Comment comment, String postAuthorUserId) {
    74	        Map<String, Object> payload = new LinkedHashMap<String, Object>();
    75	        payload.put("eventId", idGenerator.newId());
    76	        payload.put("postId", comment.getPostId());
    77	        payload.put("commentId", comment.getId());
    78	        payload.put("postAuthorUserId", postAuthorUserId);
    79	        payload.put("role", comment.getRole());
    80	        payload.put("occurredAt", Instant.now(clock).toString());
    81	        send(commentCreatedTopic, comment.getPostId(), payload);
    82	    }
    83	
    84	    private void send(String topic, String key, Map<String, Object> payload) {
    85	        try {
    86	            String json = objectMapper.writeValueAsString(payload);
    87	            kafkaTemplate.send(topic, key, json);
    88	        } catch (JsonProcessingException e) {
    89	            throw new IllegalStateException("failed to serialize event for topic " + topic, e);
    90	        }
    91	    }
    92	}
