                .body("find { it.id == '" + id + "' }.content", equalTo("Content " + id))
                .body("find { it.id == '" + id + "' }.moodEmoji", equalTo("😀"))
                .body("find { it.id == '" + id + "' }.nickname", equalTo("nick-" + id))
                .body("find { it.id == '" + id + "' }.likes", equalTo(3))
                .body("find { it.id == '" + id + "' }.createdAt",
