        executeSqlTemplate("sql/list-posts-teardown.sql", params);
        executeSqlTemplate("sql/list-posts-setup.sql", params);
        try {
            given().log().all()
                .baseUri(BASE_URL)
            .when()
                .get("/internal/posts")
            .then().log().ifValidationFails()
                .statusCode(200)
                .body("find { it.id == '" + id + "' }.category", equalTo("daily"))
                .body("find { it.id == '" + id + "' }.moodEmoji", nullValue())
                .body("find { it.id == '" + id + "' }.likes", equalTo(0));
        } finally {
            executeSqlTemplate("sql/list-posts-teardown.sql", params);
        }
    }

    @Test
    void NTC_listPosts_ordersByCreatedAtDescForOwnPosts(TestInfo info) {
        String base = testId(info);
        String idNewer = base + "N";
        String idOlder = base + "O";
        Map<String, String> newer = postParams(idNewer, "user-" + base, "Newer " + base, "mental",
                "Newer content", "NULL", "nick-" + base, "0", "2026-07-20 12:00:00");
        Map<String, String> older = postParams(idOlder, "user-" + base, "Older " + base, "mental",
                "Older content", "NULL", "nick-" + base, "0", "2026-07-20 08:00:00");

        executeSqlTemplate("sql/list-posts-teardown.sql", newer);
        executeSqlTemplate("sql/list-posts-teardown.sql", older);
        executeSqlTemplate("sql/list-posts-setup.sql", older);
        executeSqlTemplate("sql/list-posts-setup.sql", newer);
        try {
            Response response = given().log().all()
                    .baseUri(BASE_URL)
                .when()
                    .get("/internal/posts")
                .then().log().ifValidationFails()
                    .statusCode(200)
