            assertTrue(newerIndex >= 0, "newer post must be present in response");
            assertTrue(olderIndex >= 0, "older post must be present in response");
            assertTrue(newerIndex < olderIndex,
                    "createdAt DESC order expected: newer (" + newerIndex + ") before older (" + olderIndex + ")");
