import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.HashMap;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.matchesPattern;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller CommunityController (src/main/java/com/tainted/community/web/CommunityController.java)
 * @target-api POST /internal/posts (handler: createPost)
 *
 * No internal classes are imported; verification is pure HTTP (RestAssured) + direct JDBC.
 * No HTTP-based external integration exists on this call path. CommunityService#createPost
 * does publish two Kafka events (post.created, mood.logged) via CommunityEventPublisher, but
 * KafkaTemplate is a message-queue client (not HTTP), so per pipeline rule "WireMock은
 * HTTP/HTTPS 기반 외부 연동에만 적용" it is out of WireMock's scope. The controller does not
 * await the publish result, so it does not affect this endpoint's HTTP response; the test
 * environment is expected to run against a real Kafka broker (as the project's own
 * CommunityIntegrationTest already does via Testcontainers), and this black-box suite does
 * not assert on Kafka topics.
 *
 * Test-plan checklist (.nimbus/artifacts/test-plan/CommunityService_createPost.md):
 *   - NTC_branch_createPost_1 (Happy Path POST returns 201) -> covered by NTC_* below
 *   - ATC_code400 (General Bad Request 400) -> ATC_code400_missingAllRequiredFields
 * extract-key-params found no RED (branch-controlling) parameters inside
 * CommunityService#createPost itself; all @NotBlank constraints live on the DTO
 * (CreatePostRequest, Bean Validation via @Valid), confirmed by direct read of
 * CreatePostRequest.java and CommunityController#createPost. Per Step 3-A guidance those
 * validation annotations are still reflected below as VTC_* cases (NULL/EMPTY per field).
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class CreatePostBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8085");
    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/community");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "rootpw");

    private static final String UUID_PATTERN =
            "[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}";

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private String testId(TestInfo info) {
        String key = getClass().getSimpleName() + "." + info.getTestMethod().get().getName();
        return String.format("T%09d", Math.abs(key.hashCode()) % 1_000_000_000);
    }

    private static String readAll(InputStream is) throws Exception {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        byte[] chunk = new byte[4096];
        int n;
        while ((n = is.read(chunk)) != -1) {
            buffer.write(chunk, 0, n);
        }
        return new String(buffer.toByteArray(), StandardCharsets.UTF_8);
    }

    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             InputStream is = CreatePostBlackBoxTest.class.getClassLoader().getResourceAsStream(resourcePath);
             Statement stmt = conn.createStatement()) {
            String sql = readAll(is);
            for (Map.Entry<String, String> entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }
            for (String line : sql.split("\n")) {
                String trimmed = line.trim();
                if (trimmed.startsWith("--") || trimmed.isEmpty()) continue;
                if (trimmed.endsWith(";")) trimmed = trimmed.substring(0, trimmed.length() - 1);
                if (!trimmed.isEmpty()) stmt.execute(trimmed);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    private static Map<String, String> byUserId(String userId) {
        Map<String, String> m = new HashMap<>();
        m.put("USER_ID", userId);
        return m;
    }

    /** value == null -> field omitted entirely from JSON (NULL variant). */
    private static String createPostJson(String userId, String title, String category, String content,
                                          String moodEmoji, String nickname) {
        StringBuilder sb = new StringBuilder("{");
        boolean[] first = {true};
        appendField(sb, "userId", userId, first);
        appendField(sb, "title", title, first);
        appendField(sb, "category", category, first);
        appendField(sb, "content", content, first);
        appendField(sb, "moodEmoji", moodEmoji, first);
        appendField(sb, "nickname", nickname, first);
        sb.append("}");
        return sb.toString();
    }

    private static void appendField(StringBuilder sb, String name, String value, boolean[] first) {
        if (value == null) return;
        if (!first[0]) sb.append(",");
        sb.append("\"").append(name).append("\":\"").append(escape(value)).append("\"");
        first[0] = false;
    }

    private static String escape(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    @Test
    void NTC_createPost_withMoodEmoji(TestInfo info) {
        String id = testId(info);
        String userId = "user-" + id;
        Map<String, String> params = byUserId(userId);
        executeSqlTemplate("sql/create-post-teardown.sql", params);
        try {
            String json = createPostJson(userId, "Title " + id, "career", "Content " + id, "😔", "nick-" + id);
            String postId = given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body(json)
                .when()
                    .post("/internal/posts")
                .then().log().ifValidationFails()
                    .statusCode(201)
                    .body("postId", matchesPattern(UUID_PATTERN))
                    .extract().path("postId");

            try (Connection conn = getDbConnection();
                 PreparedStatement ps = conn.prepareStatement(
                         "SELECT id, title, category, content, mood_emoji, nickname, likes FROM post WHERE user_id = ?")) {
                ps.setString(1, userId);
                ResultSet rs = ps.executeQuery();
                assertTrue(rs.next(), "created post row must exist");
                assertEquals(postId, rs.getString("id"));
                assertEquals("Title " + id, rs.getString("title"));
                assertEquals("career", rs.getString("category"));
                assertEquals("Content " + id, rs.getString("content"));
                assertEquals("😔", rs.getString("mood_emoji"));
                assertEquals("nick-" + id, rs.getString("nickname"));
                assertEquals(0, rs.getInt("likes"));
            }
        } finally {
            executeSqlTemplate("sql/create-post-teardown.sql", params);
        }
    }

    @Test
    void NTC_createPost_withoutMoodEmoji(TestInfo info) {
        String id = testId(info);
        String userId = "user-" + id;
        Map<String, String> params = byUserId(userId);
        executeSqlTemplate("sql/create-post-teardown.sql", params);
        try {
            String json = createPostJson(userId, "Title " + id, "daily", "Content " + id, null, "nick-" + id);
            given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body(json)
                .when()
                    .post("/internal/posts")
                .then().log().ifValidationFails()
                    .statusCode(201)
                    .body("postId", matchesPattern(UUID_PATTERN));

            try (Connection conn = getDbConnection();
                 PreparedStatement ps = conn.prepareStatement(
                         "SELECT category, mood_emoji, likes FROM post WHERE user_id = ?")) {
                ps.setString(1, userId);
                ResultSet rs = ps.executeQuery();
                assertTrue(rs.next(), "created post row must exist");
                assertEquals("daily", rs.getString("category"));
                assertNull(rs.getString("mood_emoji"));
                assertEquals(0, rs.getInt("likes"));
            }
        } finally {
            executeSqlTemplate("sql/create-post-teardown.sql", params);
        }
    }

    @Test
    void NTC_createPost_familyCategory(TestInfo info) {
        String id = testId(info);
        String userId = "user-" + id;
        Map<String, String> params = byUserId(userId);
        executeSqlTemplate("sql/create-post-teardown.sql", params);
        try {
            String json = createPostJson(userId, "Title " + id, "family", "Content " + id, "😟", "nick-" + id);
            given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body(json)
                .when()
                    .post("/internal/posts")
                .then().log().ifValidationFails()
                    .statusCode(201)
                    .body("postId", matchesPattern(UUID_PATTERN));

            try (Connection conn = getDbConnection();
                 PreparedStatement ps = conn.prepareStatement(
                         "SELECT category, mood_emoji FROM post WHERE user_id = ?")) {
                ps.setString(1, userId);
                ResultSet rs = ps.executeQuery();
                assertTrue(rs.next(), "created post row must exist");
                assertEquals("family", rs.getString("category"));
                assertEquals("😟", rs.getString("mood_emoji"));
            }
        } finally {
            executeSqlTemplate("sql/create-post-teardown.sql", params);
        }
    }

    @Test
    void ATC_code400_missingAllRequiredFields() {
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{}")
            .when()
                .post("/internal/posts")
            .then().log().ifValidationFails()
                .statusCode(400)
                .contentType("application/problem+json")
                .body("type", equalTo("about:blank"))
                .body("title", equalTo("Validation failed"))
                .body("status", equalTo(400));
    }

    @Test
    void VTC_userId_NULL(TestInfo info) {
        assertValidationFailure(testId(info), createPostJson(null, "t", "career", "c", null, "n"));
    }

    @Test
    void VTC_userId_EMPTY(TestInfo info) {
        assertValidationFailure(testId(info), createPostJson("", "t", "career", "c", null, "n"));
    }

    @Test
    void VTC_title_NULL(TestInfo info) {
        String id = testId(info);
        assertValidationFailure(id, createPostJson("user-" + id, null, "career", "c", null, "n"));
    }

    @Test
    void VTC_title_EMPTY(TestInfo info) {
        String id = testId(info);
        assertValidationFailure(id, createPostJson("user-" + id, "", "career", "c", null, "n"));
    }

    @Test
    void VTC_category_NULL(TestInfo info) {
        String id = testId(info);
        assertValidationFailure(id, createPostJson("user-" + id, "t", null, "c", null, "n"));
    }

    @Test
    void VTC_category_EMPTY(TestInfo info) {
        String id = testId(info);
        assertValidationFailure(id, createPostJson("user-" + id, "t", "", "c", null, "n"));
    }

    @Test
    void VTC_content_NULL(TestInfo info) {
        String id = testId(info);
        assertValidationFailure(id, createPostJson("user-" + id, "t", "career", null, null, "n"));
    }

    @Test
    void VTC_content_EMPTY(TestInfo info) {
        String id = testId(info);
        assertValidationFailure(id, createPostJson("user-" + id, "t", "career", "", null, "n"));
    }

    @Test
    void VTC_nickname_NULL(TestInfo info) {
        String id = testId(info);
        assertValidationFailure(id, createPostJson("user-" + id, "t", "career", "c", null, null));
    }

    @Test
    void VTC_nickname_EMPTY(TestInfo info) {
        String id = testId(info);
        assertValidationFailure(id, createPostJson("user-" + id, "t", "career", "c", null, ""));
    }

    /**
     * Sends an invalid createPost payload and asserts the request is rejected (400) and that
     * no row was persisted for the deterministic user-${id} key, regardless of which required
     * field triggered the Bean Validation failure.
     */
    private void assertValidationFailure(String id, String json) {
        String userId = "user-" + id;
        Map<String, String> params = byUserId(userId);
        executeSqlTemplate("sql/create-post-teardown.sql", params);
        try {
            given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body(json)
                .when()
                    .post("/internal/posts")
                .then().log().ifValidationFails()
                    .statusCode(400)
                    .contentType("application/problem+json")
                    .body("status", equalTo(400));

            try (Connection conn = getDbConnection();
                 PreparedStatement ps = conn.prepareStatement("SELECT COUNT(*) AS cnt FROM post WHERE user_id = ?")) {
                ps.setString(1, userId);
                ResultSet rs = ps.executeQuery();
                assertTrue(rs.next());
                assertEquals(0, rs.getInt("cnt"), "invalid request must not persist a post row");
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        } finally {
            executeSqlTemplate("sql/create-post-teardown.sql", params);
        }
    }
}

