package com.tainted.community.blackbox;

import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.HashMap;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.matchesPattern;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller CommunityController (src/main/java/com/tainted/community/web/CommunityController.java)
 * @target-api POST /internal/posts/{id}/comments (handler: addComment)
 *
 * No internal classes are imported; verification is pure HTTP (RestAssured) + direct JDBC.
 * No HTTP-based external integration exists on this call path. CommunityService#addComment
 * publishes a Kafka comment.created event via CommunityEventPublisher; KafkaTemplate is a
 * message-queue client (not HTTP), so per pipeline rule "WireMock은 HTTP/HTTPS 기반 외부
 * 연동에만 적용" it is out of WireMock's scope and not asserted on here (see
 * CreatePostBlackBoxTest javadoc for the same reasoning).
 *
 * Test-plan checklist (.nimbus/artifacts/test-plan/CommunityService_addComment.md):
 *   - NTC_branch_addComment_2 (Happy Path POST returns 201) -> covered by NTC_* below
 *   - ATC_postId_noData (DB에 postId 조건에 맞는 데이터 없음) -> ATC_postId_noData
 *   - ATC_code400 (General Bad Request 400) -> ATC_code400_missingAllRequiredFields
 *
 * VTC plan (.nimbus/artifacts/vtc-plan/CommunityService_addComment.md): postId NULL/EMPTY
 * variants are intentionally not implemented as separate tests -- see GetPostBlackBoxTest
 * javadoc for the path-variable rationale (an empty/omitted path segment changes routing,
 * it does not exercise addComment's not-found branch). WHITE_SPACE/SPECIAL_CHAR route
 * normally and are implemented below. CreateCommentRequest's @NotBlank fields (author, role,
 * content) are reflected as VTC_* per Step 3-A guidance.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class AddCommentBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8085");
    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/community");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "rootpw");

    private static final String UUID_PATTERN =
            "[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}";

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private String testId(TestInfo info) {
        String key = getClass().getSimpleName() + "." + info.getTestMethod().get().getName();
        return String.format("T%09d", Math.abs(key.hashCode()) % 1_000_000_000);
    }

    private static String readAll(InputStream is) throws Exception {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        byte[] chunk = new byte[4096];
        int n;
        while ((n = is.read(chunk)) != -1) {
            buffer.write(chunk, 0, n);
        }
        return new String(buffer.toByteArray(), StandardCharsets.UTF_8);
    }

    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             InputStream is = AddCommentBlackBoxTest.class.getClassLoader().getResourceAsStream(resourcePath);
             Statement stmt = conn.createStatement()) {
            String sql = readAll(is);
            for (Map.Entry<String, String> entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }
            for (String line : sql.split("\n")) {
                String trimmed = line.trim();
                if (trimmed.startsWith("--") || trimmed.isEmpty()) continue;
                if (trimmed.endsWith(";")) trimmed = trimmed.substring(0, trimmed.length() - 1);
                if (!trimmed.isEmpty()) stmt.execute(trimmed);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    private static Map<String, String> postParams(String postId, String id) {
        Map<String, String> m = new HashMap<>();
        m.put("POST_ID", postId);
        m.put("USER_ID", "user-" + id);
        m.put("TITLE", "Title " + id);
        m.put("CATEGORY", "career");
        m.put("CONTENT", "Content " + id);
        m.put("NICKNAME", "nick-" + id);
        m.put("CREATED_AT", "2026-07-20 09:00:00");
        return m;
    }

    /** value == null -> field omitted entirely from JSON (NULL variant). */
    private static String commentJson(String author, String role, String content) {
        StringBuilder sb = new StringBuilder("{");
        boolean[] first = {true};
        appendField(sb, "author", author, first);
        appendField(sb, "role", role, first);
        appendField(sb, "content", content, first);
        sb.append("}");
        return sb.toString();
    }

    private static void appendField(StringBuilder sb, String name, String value, boolean[] first) {
        if (value == null) return;
        if (!first[0]) sb.append(",");
        sb.append("\"").append(name).append("\":\"").append(escape(value)).append("\"");
        first[0] = false;
    }

    private static String escape(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    @Test
    void NTC_addComment_empathicRole(TestInfo info) {
        String id = testId(info);
        String postId = id + "-post";
        Map<String, String> params = postParams(postId, id);
        executeSqlTemplate("sql/add-comment-teardown.sql", params);
        executeSqlTemplate("sql/add-comment-setup.sql", params);
        try {
            String json = commentJson("author-" + id, "empathic", "comment content " + id);
            given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body(json)
                .when()
                    .post("/internal/posts/{id}/comments", postId)
                .then().log().ifValidationFails()
                    .statusCode(201)
                    .body("commentId", matchesPattern(UUID_PATTERN))
                    .body("postId", equalTo(postId))
                    .body("role", equalTo("empathic"));

            try (Connection conn = getDbConnection();
                 PreparedStatement ps = conn.prepareStatement(
                         "SELECT author, role, content FROM comment WHERE post_id = ?")) {
                ps.setString(1, postId);
                ResultSet rs = ps.executeQuery();
                assertTrue(rs.next(), "comment row must be persisted");
                assertEquals("author-" + id, rs.getString("author"));
                assertEquals("empathic", rs.getString("role"));
                assertEquals("comment content " + id, rs.getString("content"));
            }
        } finally {
            executeSqlTemplate("sql/add-comment-teardown.sql", params);
        }
    }

    @Test
    void NTC_addComment_analyticalRole(TestInfo info) {
        String id = testId(info);
        String postId = id + "-post";
        Map<String, String> params = postParams(postId, id);
        executeSqlTemplate("sql/add-comment-teardown.sql", params);
        executeSqlTemplate("sql/add-comment-setup.sql", params);
        try {
            String json = commentJson("author-" + id, "analytical", "comment content " + id);
            given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body(json)
                .when()
                    .post("/internal/posts/{id}/comments", postId)
                .then().log().ifValidationFails()
                    .statusCode(201)
                    .body("postId", equalTo(postId))
                    .body("role", equalTo("analytical"));
        } finally {
            executeSqlTemplate("sql/add-comment-teardown.sql", params);
        }
    }

    @Test
    void NTC_addComment_multipleCommentsOnSamePost(TestInfo info) {
        String id = testId(info);
        String postId = id + "-post";
        Map<String, String> params = postParams(postId, id);
        executeSqlTemplate("sql/add-comment-teardown.sql", params);
        executeSqlTemplate("sql/add-comment-setup.sql", params);
        try {
            given().baseUri(BASE_URL).contentType(ContentType.JSON)
                    .body(commentJson("author-a-" + id, "sincere", "first comment " + id))
                .when().post("/internal/posts/{id}/comments", postId)
                .then().statusCode(201);

            given().baseUri(BASE_URL).contentType(ContentType.JSON)
                    .body(commentJson("author-b-" + id, "hopeful", "second comment " + id))
                .when().post("/internal/posts/{id}/comments", postId)
                .then().statusCode(201);

            try (Connection conn = getDbConnection();
                 PreparedStatement ps = conn.prepareStatement(
                         "SELECT COUNT(*) AS cnt FROM comment WHERE post_id = ?")) {
                ps.setString(1, postId);
                ResultSet rs = ps.executeQuery();
                assertTrue(rs.next());
                assertEquals(2, rs.getInt("cnt"));
            }
        } finally {
            executeSqlTemplate("sql/add-comment-teardown.sql", params);
        }
    }

    @Test
    void ATC_postId_noData(TestInfo info) {
        String id = testId(info);
        String postId = id + "-missing";
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body(commentJson("author-" + id, "empathic", "content " + id))
            .when()
                .post("/internal/posts/{id}/comments", postId)
