        assertCommentValidationFailure(testId(info), commentJson("", "empathic", "content"));
    }

    @Test
    void VTC_role_NULL(TestInfo info) {
        assertCommentValidationFailure(testId(info), commentJson("author", null, "content"));
    }

    @Test
    void VTC_role_EMPTY(TestInfo info) {
        assertCommentValidationFailure(testId(info), commentJson("author", "", "content"));
    }

    @Test
    void VTC_content_NULL(TestInfo info) {
        assertCommentValidationFailure(testId(info), commentJson("author", "empathic", null));
    }

    @Test
    void VTC_content_EMPTY(TestInfo info) {
        assertCommentValidationFailure(testId(info), commentJson("author", "empathic", ""));
    }

    private void assertCommentValidationFailure(String id, String json) {
        String postId = id + "-post";
        Map<String, String> params = postParams(postId, id);
        executeSqlTemplate("sql/add-comment-teardown.sql", params);
        executeSqlTemplate("sql/add-comment-setup.sql", params);
        try {
            given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body(json)
                .when()
                    .post("/internal/posts/{id}/comments", postId)
                .then().log().ifValidationFails()
                    .statusCode(400)
                    .contentType("application/problem+json")
                    .body("status", equalTo(400));

            try (Connection conn = getDbConnection();
                 PreparedStatement ps = conn.prepareStatement(
                         "SELECT COUNT(*) AS cnt FROM comment WHERE post_id = ?")) {
                ps.setString(1, postId);
                ResultSet rs = ps.executeQuery();
                assertTrue(rs.next());
                assertEquals(0, rs.getInt("cnt"), "invalid request must not persist a comment row");
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        } finally {
            executeSqlTemplate("sql/add-comment-teardown.sql", params);
        }
    }
}

